contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v1, uint v2) public payable {
        c.SetMinSum(v1); if (__ESBMC_reverted()) return;
        uint afterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool secondReverted;
        c.SetMinSum(v2); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        assert(afterFirst == v1 && secondReverted && c.MinSum() == v1);
    }

    receive() external payable {}
}

