// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 v1, uint256 v2) internal {
        try c.SetMinSum(v1) {} catch { return; }
        uint256 afterFirst;
        try c.MinSum() returns (uint256 __r) { afterFirst = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        bool secondReverted;
        try c.SetMinSum(v2) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        assertTrue(afterFirst == v1 && secondReverted && c.MinSum() == v1);
    }

    function testFuzz_run(uint256 v1, uint256 v2) public {
        _run(v1, v2);
    }

    receive() external payable {}
}
